CONFIG = json.loads('{"name": "ace-h2h-v1", "line": "ace", "mode": "h2h", "seed": 1234, "max_new_tokens": 256, "corpus_file": "verdicts_train.jsonl", "heldout_file": "ace-heldout-v1.jsonl", "expected_heldout_sha256": "23452d59cdcbf897a54bbdb3fbea8d89a449efe6c7d6f543b906fe64e91cd632", "files": {"verdicts_train.jsonl": {"sha256": "6b2428c80a8534013c711e8be2aadd7fe8ae16733076f14c58ca9c99d4d45ce1", "bytes": 46483, "b64gz": ""}, "ace-heldout-v1.jsonl": {"sha256": "23452d59cdcbf897a54bbdb3fbea8d89a449efe6c7d6f543b906fe64e91cd632", "bytes": 13051, "b64gz": ""}}, "candidates": ["Qwen/Qwen2.5-7B-Instruct", "mistralai/Mistral-7B-Instruct-v0.3", "Qwen/Qwen2.5-Coder-7B-Instruct"], "h2h_max_items": 40}')

# ------------------------------------------------------------------------------------------- inlined scoring module
"""Mechanical Part A scoring for GHOST-QUAL-001 and ACE-QUAL-001. Deterministic; no model judges anything.

Output contracts, taken from the datasets' own response format:
  GHOST: a line "FAILURE CLASS: <EGRESS|TRANSPORT|FAULT|STATE|UNKNOWN|NONE>"
  ACE:   a line "VERDICT: <STATE>", using the recorded registry state vocabulary
An answer without a parsable contract line scores as a miss (format is part of the skill), never as a guess.
This module reports EVIDENCE for Part A only. A battery verdict also needs Parts B and C, the blind rubric and
independent verification.
"""

import hashlib
import json
import re
from typing import Any, Dict, List, Optional

GHOST_CLASSES = ("EGRESS", "TRANSPORT", "FAULT", "STATE", "UNKNOWN", "NONE")
FAULT_CLASSES = frozenset(("EGRESS", "TRANSPORT", "FAULT", "STATE"))
_CLASS_RE = re.compile(r"FAILURE\s+CLASS\s*:\s*\**\s*([A-Z]+)", re.I)
_VERDICT_RE = re.compile(r"VERDICT\s*:\s*\**\s*([A-Z][A-Z_-]+)", re.I)


def sha256_file(path: str) -> str:
    return hashlib.sha256(open(path, "rb").read()).hexdigest()


_LEADING_CLASS_RE = re.compile(r"^\s*\**\s*(EGRESS|TRANSPORT|FAULT|STATE|UNKNOWN|NONE)\b")


def parse_class(text: str) -> Optional[str]:
    """The labelled line wins. Otherwise the answer may OPEN with the class, which is how the dataset writes UNKNOWN
    answers ("UNKNOWN — the record does not determine…"). A class word buried mid-prose is not an answer."""
    m = _CLASS_RE.search(text or "")
    if m:
        c = m.group(1).upper()
        return c if c in GHOST_CLASSES else None
    m = _LEADING_CLASS_RE.match(text or "")
    return m.group(1) if m else None


def parse_verdict(text: str) -> Optional[str]:
    m = _VERDICT_RE.search(text or "")
    return m.group(1).upper().rstrip("-_") if m else None


def truth_of(line: str, record: Dict[str, Any]) -> Optional[str]:
    return parse_class(record["response"]) if line == "ghost" else parse_verdict(record["response"])


def score_part_a(line: str, heldout: List[Dict[str, Any]], answers: Dict[str, str]) -> Dict[str, Any]:
    """answers: {record id -> model output}. Returns per-item results and summary metrics."""
    if line not in ("ghost", "ace"):
        raise ValueError("line must be ghost or ace")
    parse = parse_class if line == "ghost" else parse_verdict
    items, correct, determined, restraint_violations, unknown_violations, missing = [], 0, 0, 0, 0, 0
    for r in heldout:
        rid = str(r["id"])
        truth = truth_of(line, r)
        if truth is None:
            raise ValueError(f"held-out record {rid} has no parsable ground truth; the battery is void")
        out = answers.get(rid)
        if out is None:
            missing += 1
        got = parse(out or "")
        ok = got == truth
        item = {"id": rid, "type": r.get("type"), "truth": truth, "answer": got, "match": ok,
                "parsed": got is not None}
        if line == "ghost":
            if truth != "UNKNOWN":
                determined += 1
                correct += int(ok)
            if truth == "NONE" and got in FAULT_CLASSES:
                restraint_violations += 1
                item["restraint_violation"] = True
            if truth == "UNKNOWN" and got != "UNKNOWN":
                unknown_violations += 1  # a determined class on an underdetermined case = fabrication event
                item["fabrication_event"] = True
        else:
            determined += 1
            correct += int(ok)
        items.append(item)
    summary = {"line": line, "cases": len(heldout), "answered": len(heldout) - missing,
               "determined_cases": determined, "determined_correct": correct,
               "accuracy": round(correct / determined, 4) if determined else None}
    if line == "ghost":
        summary.update(restraint_violations=restraint_violations, unknown_law_violations=unknown_violations)
    return {"summary": summary, "items": items,
            "status": "PART-A-EVIDENCE-ONLY — a battery verdict also needs Parts B+C, the blind rubric and "
                      "independent verification"}


def compare(base: Dict[str, Any], tuned: Dict[str, Any]) -> Dict[str, Any]:
    b, t = base["summary"]["accuracy"], tuned["summary"]["accuracy"]
    return {"base_accuracy": b, "tuned_accuracy": t,
            "delta_points": None if b is None or t is None else round(100 * (t - b), 1)}


def load_jsonl(path: str) -> List[Dict[str, Any]]:
    with open(path, encoding="utf-8") as f:
        return [json.loads(l) for l in f if l.strip()]

# ------------------------------------------------------------------------------------------- end of scoring module

PINS = ["transformers==4.56.2", "peft==0.13.2", "accelerate==1.1.1", "bitsandbytes>=0.45.0"]


class Abort(RuntimeError):
    """A law was broken; the run stops and says why, before spending more compute."""


def log(msg):
    print(f"[{time.strftime('%H:%M:%S')}] {msg}", flush=True)


def materialize(workdir):
    paths = {}
    os.makedirs(workdir, exist_ok=True)
    for name, spec in CONFIG["files"].items():
        data = gzip.decompress(base64.b64decode(spec["b64gz"]))
        got = hashlib.sha256(data).hexdigest()
        if got != spec["sha256"]:
            raise Abort(f"embedded file {name} hash {got} != {spec['sha256']}")
        p = os.path.join(workdir, name)
        with open(p, "wb") as f:
            f.write(data)
        paths[name] = p
    held = CONFIG.get("heldout_file")
    if held:
        want = CONFIG["expected_heldout_sha256"]
        if CONFIG["files"][held]["sha256"] != want:
            raise Abort(f"held-out hash {CONFIG['files'][held]['sha256']} != manifest {want}: battery void")
    return paths


def normalize_records(records):
    """Dataset files stay byte-identical (they are hash-gated). Known shape defects are fixed in memory and reported:
    an instruction stored as a list of strings is joined with newlines (seen in ghost-v1 GHOST-C-019)."""
    fixed = []
    for r in records:
        ins = r.get("instruction")
        if isinstance(ins, list) and all(isinstance(x, str) for x in ins):
            r["instruction"] = "\n".join(ins)
            fixed.append(str(r.get("id")))
        elif "instruction" in r and not isinstance(ins, str):
            raise Abort(f"record {r.get('id')} has an instruction of type {type(ins).__name__}")
    return fixed


def _norm(s):
    return " ".join((s or "").split()).lower()


def assert_no_contamination(corpus, heldout):
    train = {_norm(r.get("instruction", "")) for r in corpus}
    leaked = [r["id"] for r in heldout if _norm(r["instruction"]) in train]
    if leaked:
        raise Abort(f"contamination: held-out records {leaked} appear in the training corpus")


def prompt_text(tok, instruction):
    if getattr(tok, "chat_template", None):
        return tok.apply_chat_template([{"role": "user", "content": instruction}], tokenize=False,
                                       add_generation_prompt=True)
    return f"### Instruction:\n{instruction}\n\n### Response:\n"


def record_text(r):
    return r.get("text") if r.get("type") == "doc" or "instruction" not in r else None


# ------------------------------------------------------------------------------------------------ model loading
def ensure_pins():
    if os.environ.get("GENESIS_SKIP_PIP") == "1":
        return
    subprocess.run([sys.executable, "-m", "pip", "install", "-q", *PINS], check=True)


def tiny_model_and_tokenizer(texts, seed):
    """Dry-run only: a random 2-layer Llama + a tokenizer trained here. Proves the mechanics, never quality."""
    import torch
    from tokenizers import Tokenizer, models, pre_tokenizers, trainers, decoders
    from transformers import LlamaConfig, LlamaForCausalLM, PreTrainedTokenizerFast
    tk = Tokenizer(models.BPE(unk_token="<unk>"))
    tk.pre_tokenizer = pre_tokenizers.ByteLevel(add_prefix_space=False)
    tk.decoder = decoders.ByteLevel()
    tk.train_from_iterator(texts, trainers.BpeTrainer(vocab_size=1200, special_tokens=["<unk>", "<s>", "</s>", "<pad>"],
                                                      initial_alphabet=pre_tokenizers.ByteLevel.alphabet()))
    tok = PreTrainedTokenizerFast(tokenizer_object=tk, unk_token="<unk>", bos_token="<s>", eos_token="</s>",
                                  pad_token="<pad>")
    torch.manual_seed(seed)
    cfg = LlamaConfig(vocab_size=len(tok), hidden_size=64, intermediate_size=128, num_hidden_layers=2,
                      num_attention_heads=4, num_key_value_heads=4, max_position_embeddings=2048,
                      bos_token_id=tok.bos_token_id, eos_token_id=tok.eos_token_id, pad_token_id=tok.pad_token_id)
    return LlamaForCausalLM(cfg), tok


def load_model(name, dry, texts, seed):
    if dry:
        return tiny_model_and_tokenizer(texts, seed)
    import torch
    from transformers import AutoModelForCausalLM, AutoTokenizer, BitsAndBytesConfig
    tok = AutoTokenizer.from_pretrained(name)
    if tok.pad_token is None:
        tok.pad_token = tok.eos_token
    q = BitsAndBytesConfig(load_in_4bit=True, bnb_4bit_quant_type="nf4", bnb_4bit_use_double_quant=True,
                           bnb_4bit_compute_dtype=torch.float16)  # T4 has no bf16
    model = AutoModelForCausalLM.from_pretrained(name, quantization_config=q, device_map="auto",
                                                 torch_dtype=torch.float16)
    return model, tok


# ------------------------------------------------------------------------------------------------ generation
def generate(model, tok, records, max_new_tokens):
    import torch
    model.eval()
    dev = next(model.parameters()).device
    out = {}
    for r in records:
        enc = tok(prompt_text(tok, r["instruction"]), return_tensors="pt", return_token_type_ids=False).to(dev)
        with torch.no_grad():
            ids = model.generate(**enc, max_new_tokens=max_new_tokens, do_sample=False, num_beams=1,
                                 pad_token_id=tok.pad_token_id, eos_token_id=tok.eos_token_id)
        out[str(r["id"])] = tok.decode(ids[0, enc["input_ids"].shape[1]:], skip_special_tokens=True)
    return out


def write_sealed(path, answers):
    with open(path, "w", encoding="utf-8") as f:
        for k in sorted(answers):
            f.write(json.dumps({"id": k, "answer": answers[k]}, ensure_ascii=False) + "\n")
    return sha256_file(path)


# ------------------------------------------------------------------------------------------------ training
def build_examples(tok, corpus, max_len):
    ex = []
    for r in corpus:
        doc = record_text(r)
        if doc is not None:
            ids = tok(doc + (tok.eos_token or ""), truncation=True, max_length=max_len)["input_ids"]
            ex.append((ids, list(ids)))
            continue
        p = tok(prompt_text(tok, r["instruction"]))["input_ids"]
        a = tok(r["response"] + (tok.eos_token or ""), add_special_tokens=False)["input_ids"]
        ids = (p + a)[:max_len]
        labels = ([-100] * len(p) + a)[:max_len]  # loss only on the answer
        if any(l != -100 for l in labels):
            ex.append((ids, labels))
    return ex


def train_lora(model, tok, corpus, cfg, dry, seed):
    import torch
    from peft import LoraConfig, get_peft_model, prepare_model_for_kbit_training
    random.seed(seed)
    torch.manual_seed(seed)
    if not dry:
        model = prepare_model_for_kbit_training(model)
    targets = ["q_proj", "k_proj", "v_proj", "o_proj"] if dry else \
        ["q_proj", "k_proj", "v_proj", "o_proj", "gate_proj", "up_proj", "down_proj"]
    model = get_peft_model(model, LoraConfig(r=cfg["lora_r"], lora_alpha=cfg["lora_alpha"],
                                             lora_dropout=cfg["lora_dropout"], target_modules=targets,
                                             task_type="CAUSAL_LM"))
    examples = build_examples(tok, corpus, cfg["max_len"])
    opt = torch.optim.AdamW([p for p in model.parameters() if p.requires_grad], lr=cfg["lr"])
    dev = next(model.parameters()).device
    model.train()
    losses, step = [], 0
    for epoch in range(cfg["epochs"]):
        order = list(range(len(examples)))
        random.shuffle(order)
        for i, j in enumerate(order):
            ids, labels = examples[j]
            t_ids = torch.tensor([ids], device=dev)
            t_lab = torch.tensor([labels], device=dev)
            loss = model(input_ids=t_ids, labels=t_lab).loss / cfg["grad_accum"]
            loss.backward()
            if (i + 1) % cfg["grad_accum"] == 0 or i + 1 == len(order):
                opt.step()
                opt.zero_grad()
                step += 1
                losses.append(round(loss.item() * cfg["grad_accum"], 4))
                if dry and step >= cfg.get("dry_max_steps", 4):
                    return model, losses
        log(f"epoch {epoch + 1}/{cfg['epochs']} done, last loss {losses[-1] if losses else None}")
    return model, losses


# ------------------------------------------------------------------------------------------------ modes
def run(out_dir, dry):
    t0 = time.time()
    os.makedirs(out_dir, exist_ok=True)
    manifest = {"kernel": CONFIG["name"], "line": CONFIG["line"], "mode": CONFIG["mode"], "dry_run": dry,
                "pins": PINS, "python": platform.python_version(), "config": {k: v for k, v in CONFIG.items()
                                                                                if k != "files"},
                "files": {n: s["sha256"] for n, s in CONFIG["files"].items()}, "events": []}

    def event(kind, **kw):
        manifest["events"].append({"t": round(time.time() - t0, 2), "kind": kind, **kw})
        with open(os.path.join(out_dir, "run_manifest.json"), "w") as f:
            json.dump(manifest, f, indent=1)

    paths = materialize(os.path.join(out_dir, "data"))
    corpus = load_jsonl(paths[CONFIG["corpus_file"]])
    heldout = load_jsonl(paths[CONFIG["heldout_file"]]) if CONFIG.get("heldout_file") else []
    normalized = normalize_records(corpus) + normalize_records(heldout)
    if heldout:
        assert_no_contamination(corpus, heldout)
    event("data_verified", corpus=len(corpus), heldout=len(heldout), normalized_list_instructions=normalized)
    if not dry:
        ensure_pins()
    texts = [r.get("instruction", "") + "\n" + r.get("response", r.get("text", "")) for r in corpus + heldout]
    line, seed = CONFIG["line"], CONFIG["seed"]

    if CONFIG["mode"] == "h2h":
        prompts = [r for r in corpus if "instruction" in r and truth_of(line, r) is not None][:CONFIG["h2h_max_items"]]
        ranking = []
        for name in CONFIG["candidates"]:
            model, tok = load_model(name, dry, texts, seed)
            answers = generate(model, tok, prompts, CONFIG["max_new_tokens"])
            rep = score_part_a(line, prompts, answers)
            ranking.append({"candidate": name, **rep["summary"],
                            "outputs_sha256": write_sealed(os.path.join(out_dir, f"h2h_{name.replace('/', '__')}.jsonl"),
                                                           answers)})
            event("h2h_candidate_done", candidate=name, accuracy=rep["summary"]["accuracy"])
            del model
        ranking.sort(key=lambda r: (-(r["accuracy"] or 0), r["candidate"]))
        report = {"line": line, "selection_set": "training split (never the held-out set)", "items": len(prompts),
                  "ranking": ranking, "winner": ranking[0]["candidate"] if ranking else None}
        with open(os.path.join(out_dir, "h2h_report.json"), "w") as f:
            json.dump(report, f, indent=1)
        event("done", seconds=round(time.time() - t0, 1))
        return report

    model, tok = load_model(CONFIG["base_model"], dry, texts, seed)
    base_answers = generate(model, tok, heldout, CONFIG["max_new_tokens"])
    base_seal = write_sealed(os.path.join(out_dir, "base_partA.jsonl"), base_answers)
    event("base_sealed", sha256=base_seal)  # sealed BEFORE any training step
    model, losses = train_lora(model, tok, corpus, CONFIG["lora"], dry, seed)
    event("trained", steps=len(losses), losses=losses[-20:])
    tuned_answers = generate(model, tok, heldout, CONFIG["max_new_tokens"])
    tuned_seal = write_sealed(os.path.join(out_dir, "tuned_partA.jsonl"), tuned_answers)
    event("tuned_sealed", sha256=tuned_seal)
    adapter_dir = os.path.join(out_dir, "adapter")
    model.save_pretrained(adapter_dir)
    adapter_hashes = {f: sha256_file(os.path.join(adapter_dir, f)) for f in sorted(os.listdir(adapter_dir))}
    base_rep = score_part_a(line, heldout, base_answers)
    tuned_rep = score_part_a(line, heldout, tuned_answers)
    report = {"line": line, "base_model": CONFIG["base_model"], "base": base_rep, "tuned": tuned_rep,
              "comparison": compare(base_rep, tuned_rep), "seals": {"base": base_seal, "tuned": tuned_seal},
              "adapter_sha256": adapter_hashes,
              "status": "PART-A-EVIDENCE-ONLY — not a battery verdict (Parts B+C, blind rubric and independent "
                        "verification are required; see the QUAL-001 spec)"}
    with open(os.path.join(out_dir, "partA_report.json"), "w") as f:
        json.dump(report, f, indent=1)
    event("done", seconds=round(time.time() - t0, 1))
    return report


def main(argv=None):
    ap = argparse.ArgumentParser()
    ap.add_argument("--dry-run", action="store_true", help="CPU, tiny random model: proves mechanics only")
    ap.add_argument("--out", default="/kaggle/working" if os.path.isdir("/kaggle/working") else "out")
    a = ap.parse_args(argv)
    try:
        rep = run(a.out, a.dry_run)
    except Abort as exc:
        log(f"ABORT: {exc}")
        with open(os.path.join(a.out, "ABORTED.txt"), "w") as f:
            f.write(str(exc) + "\n")
        return 2
    log("report: " + json.dumps(rep.get("comparison") or rep.get("winner")))
    return 0


if __name__ == "__main__":
    sys.exit(main())
